    w(f"nest_{d}.py",body)
# complex conditional: operators in one condition
for k in (2,3,4,5):
    cond=" and ".join(f"x > {i}" for i in range(k))
    w(f"cond_{k}.py", f"def f(x):\n    if {cond}:\n        return 1\n    return 0\n")
# file LoC sweep: many tiny functions
for n in (200,500,800,1000,1200):
